SELECT QUARTER(a.opened_date) AS opened_quarter, ROUND(STDDEV(t.amount), 2) AS stddev_amount, SUM(CASE WHEN t.txn_type = 'DEBIT' THEN t.amount ELSE 0 END) AS debit_amount FROM transactions t RIGHT JOIN accounts a ON t.account_id = a.id WHERE t.txn_type IN ('CREDIT', 'FEE') GROUP BY QUARTER(a.opened_date) HAVING SUM(CASE WHEN t.txn_type = 'DEBIT' THEN t.amount ELSE 0 END) > 48 ORDER BY stddev_amount DESC
